using FluentValidation;
namespace WhatsBiz.Application.Features.Suppliers;
public sealed class SupplierInputValidator:AbstractValidator<SupplierInput>{public SupplierInputValidator(){RuleFor(x=>x.SupplierCode).NotEmpty().MaximumLength(50);RuleFor(x=>x.SupplierName).NotEmpty().MaximumLength(250);RuleFor(x=>x.SupplierType).NotEmpty().MaximumLength(50);RuleFor(x=>x.GSTIN).Matches("^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][1-9A-Z]Z[0-9A-Z]$").When(x=>!string.IsNullOrWhiteSpace(x.GSTIN));RuleFor(x=>x.PAN).Matches("^[A-Z]{5}[0-9]{4}[A-Z]$").When(x=>!string.IsNullOrWhiteSpace(x.PAN));RuleFor(x=>x.Email).EmailAddress().When(x=>!string.IsNullOrWhiteSpace(x.Email));RuleFor(x=>x.Mobile).Matches("^[6-9][0-9]{9}$").When(x=>!string.IsNullOrWhiteSpace(x.Mobile));RuleFor(x=>x.Currency).NotEmpty().Length(3);RuleFor(x=>x.CreditLimit).GreaterThanOrEqualTo(0);RuleForEach(x=>x.Contacts).ChildRules(c=>{c.RuleFor(x=>x.ContactPerson).NotEmpty();c.RuleFor(x=>x.Email).EmailAddress().When(x=>!string.IsNullOrWhiteSpace(x.Email));c.RuleFor(x=>x.Mobile).Matches("^[6-9][0-9]{9}$").When(x=>!string.IsNullOrWhiteSpace(x.Mobile));});RuleForEach(x=>x.Addresses).ChildRules(a=>{a.RuleFor(x=>x.AddressType).NotEmpty();a.RuleFor(x=>x.AddressLine1).NotEmpty();a.RuleFor(x=>x.City).NotEmpty();a.RuleFor(x=>x.State).NotEmpty();a.RuleFor(x=>x.Country).NotEmpty();a.RuleFor(x=>x.PostalCode).NotEmpty();});RuleForEach(x=>x.BankAccounts).ChildRules(b=>{b.RuleFor(x=>x.BankName).NotEmpty();b.RuleFor(x=>x.AccountNumber).NotEmpty();b.RuleFor(x=>x.IFSCCode).Matches("^[A-Z]{4}0[A-Z0-9]{6}$").When(x=>!string.IsNullOrWhiteSpace(x.IFSCCode));});}}
public sealed class CreateSupplierCommandValidator:AbstractValidator<CreateSupplierCommand>{public CreateSupplierCommandValidator()=>RuleFor(x=>x.Input).SetValidator(new SupplierInputValidator());}
public sealed class UpdateSupplierCommandValidator:AbstractValidator<UpdateSupplierCommand>{public UpdateSupplierCommandValidator(){RuleFor(x=>x.Id).NotEmpty();RuleFor(x=>x.Input).SetValidator(new SupplierInputValidator());}}
public sealed class GetSuppliersQueryValidator:AbstractValidator<GetSuppliersQuery>{public GetSuppliersQueryValidator(){RuleFor(x=>x.PageNumber).GreaterThan(0);RuleFor(x=>x.PageSize).InclusiveBetween(1,200);}}
public sealed class UploadSupplierDocumentCommandValidator:AbstractValidator<UploadSupplierDocumentCommand>{private static readonly string[] Types=["GST Certificate","PAN Card","MSME Certificate","Cancelled Cheque","Agreement","Other"];public UploadSupplierDocumentCommandValidator(){RuleFor(x=>x.Type).Must(Types.Contains);RuleFor(x=>x.FileName).NotEmpty().MaximumLength(255);RuleFor(x=>x.Data).NotEmpty().Must(x=>x.Length<=10*1024*1024).WithMessage("Document cannot exceed 10 MB.");}}
